using SevenSteps.Contracts;
using UnityEngine;

namespace SevenSteps.Game
{
    /// <summary>
    /// Every asset the game uses, in one place. Generated by Seven Steps > Build Assets and Scene
    /// (SevenSteps.EditorTools.ProjectSetup). The board draws only through <see cref="tileSet"/>; to swap art, point it
    /// at another TileSet asset. The v0 prefab fields stay as the source TileSetBuilder reads for the placeholder set.
    /// </summary>
    [CreateAssetMenu(menuName = "Seven Steps/Game Assets")]
    public sealed class GameAssets : ScriptableObject
    {
        [Header("Data")]
        public TextAsset levelsJson;
        [Tooltip("Data/chapters.json (docs/architecture.md 6.4). Empty until the chapters land: every stage is the first chapter.")]
        public TextAsset chaptersJson;
        [Tooltip("UI string tables per language, Data/Strings/<code>.json (docs/architecture.md 13.2). ko is required.")]
        public SevenSteps.Contracts.StringTableAsset[] strings = new SevenSteps.Contracts.StringTableAsset[0];
        [Tooltip("Data/story.json (docs/architecture.md 16, StoryCatalog). Empty = no story lines (the game runs without them).")]
        public TextAsset storyJson;
        [Tooltip("Story pictures by key (StoryImageSet, art). Empty = text without pictures.")]
        public StoryImageSet storyImages;
        [Tooltip("Data/cutscenes.json (design/story/cutscenes.md, CutsceneCatalog): the storybook prologue / epilogue. Empty = no cutscenes.")]
        public TextAsset cutscenesJson;
        [Tooltip("Cutscene pictures by key cutscene.<scene>.<page> (Data/CutsceneImages.asset, art). Empty sprite = the plain card.")]
        public StoryImageSet cutsceneImages;
        public Font font;
        [Tooltip("UI look: font, colors, panel prefabs (docs/scene-flow.md S6). Default Data/UiTheme_Default.asset")]
        public UI.UiTheme uiTheme;
        [Tooltip("Stage select v4 planet bodies (meshes, materials; docs/stage-select-transitions.md). Data/PlanetBodies.asset")]
        public UI.Planets.PlanetBodySet planetBodies;
        [Tooltip("Map planet sprites (V7 cutouts): Data/PlanetMapSpriteSet.asset, an IPlanetMapSprites (Art type). Empty = the planetBodies meshes on the map")]
        public ScriptableObject planetMapSprites;
        /// <see cref="planetMapSprites"/> as the map reads it; null when unset. Set but not an IPlanetMapSprites: an error.
        public UI.Planets.IPlanetMapSprites PlanetMapSprites =>
            planetMapSprites == null ? null : planetMapSprites as UI.Planets.IPlanetMapSprites ?? throw new System.InvalidOperationException($"[SevenSteps] GameAssets.planetMapSprites ({planetMapSprites.name}) is not an IPlanetMapSprites");
        [Tooltip("Planet surface paintings (V7, S2: projected on the surface body): Art's mapping, an IPlanetSurfaceArt. Empty = the planetBodies body on the surface")]
        public ScriptableObject planetSurfaceArt;
        /// <see cref="planetSurfaceArt"/> as the surface view reads it; null when unset. Set but not an IPlanetSurfaceArt: an error.
        public UI.Planets.IPlanetSurfaceArt PlanetSurfaceArt =>
            planetSurfaceArt == null ? null : planetSurfaceArt as UI.Planets.IPlanetSurfaceArt ?? throw new System.InvalidOperationException($"[SevenSteps] GameAssets.planetSurfaceArt ({planetSurfaceArt.name}) is not an IPlanetSurfaceArt");
        [Tooltip("U5 icons and sprites (docs/ui-u5-kit.md 1, 1.1): Data/UiIconSet.asset, filled from the Codex manifest; empty entries draw line placeholders")]
        public UI.U5.UiIconSet uiIcons;

        [Header("Board art")]
        [Tooltip("Tile/actor prefab mapping used by the board (docs/architecture.md 7). AppConfig.tileSet overrides this when set.")]
        public TileSet tileSet;

        [Header("v0 placeholder prefabs: source for TileSetBuilder only, not read by the game")]
        public GameObject floorA;
        public GameObject floorB;
        public GameObject wall;
        public GameObject pit;
        public GameObject ice;
        public GameObject cracked;
        public GameObject bridge;
        public GameObject exit;
        [Tooltip("Number gate. Child named \"Arch\" gets gateIdle/gateGo material.")]
        public GameObject gate;
        public GameObject plateA, plateB, plateC;
        [Tooltip("Door. Child named \"Bars\" sinks when the door is open.")]
        public GameObject doorA, doorB, doorC;

        [Header("Actors and markers")]
        public GameObject player;
        public GameObject statue;
        public GameObject startMarker;
        public GameObject oldStartMarker;
        public GameObject footprint;
        [Tooltip("Lucky 7th step stamp. Its renderer's _BaseColor alpha is faded out.")]
        public GameObject luckyRing;

        [Header("Materials")]
        public Material gateIdle;
        public Material gateGo;

        [Header("Sound")]
        public AudioClip sfxStep;
        public AudioClip sfxLucky;
        public AudioClip sfxStone;
        public AudioClip sfxSwitch;
        public AudioClip sfxFall;
        public AudioClip sfxBump;
        public AudioClip sfxBridge;
        public AudioClip sfxCrumble;
        public AudioClip sfxUndo;
        public AudioClip sfxWin;
        public AudioClip sfxLose;
        [Tooltip("Data/Sounds.asset: music and the newer effects by id (SoundIds; Assets/Shared/Audio/<id>.ogg|.wav, wired by setup)")]
        public SoundCatalog sounds;

        [Header("Palette")]
        public Color background = new Color32(0x15, 0x13, 0x1c, 0xff);

        public GameObject Plate(char c) => c == 'a' ? plateA : c == 'b' ? plateB : plateC;
        public GameObject Door(char c) => c == 'A' ? doorA : c == 'B' ? doorB : doorC;
    }
}
